using FloppyUtils.SourceGen.Ext.Extensions;
using FloppyUtils.SourceGen.Ext.Helpers;
using FloppyUtils.SourceGen.Helpers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace FloppyUtils.SourceGen.Generators;

[Generator]
public sealed class ScopedEventsGenerator : IIncrementalGenerator
{
    internal const string Attribute = "FloppyUtils.SourceGen.Attributes.ScopedEventsAttribute";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var infos = context.SyntaxProvider.ForAttributeWithMetadataName(
            Attribute,
            static (node, _) => node is ClassDeclarationSyntax,
            static (context, token) => context.TargetSymbol is INamedTypeSymbol symbol ? Parse(context, symbol, token) : default
        ).Where(i => i != default);

        context.RegisterSourceOutput(
            infos,
            static (context, item) =>
            {
                if (item.Item1 is { } diag)
                {
                    context.ReportDiagnostic(diag.Create());
                }

                if (item.Item2 is { } info)
                {
                    context.AddSource($"{info.Hierarchy.FullName}.ScopedEvents.g.cs", Generate(info, true, context.CancellationToken));
                }
            }
        );
    }

    internal static (DiagnosticInfo?, Info?) Parse(in GeneratorAttributeSyntaxContext context, INamedTypeSymbol symbol, CancellationToken token)
    {
        using var events = new ImmutableArrayBuilder<(string, string)>();

        foreach (var member in symbol.GetMembers())
        {
            if (member.IsStatic || member.DeclaredAccessibility != Accessibility.Public ||
                member is not IEventSymbol ev)
            {
                continue;
            }

            events.Add((ev.Type.GetNameWithContainingTypeAndNamespace(), ev.Name));
        }

        Info scoped = new(
            symbol.GetHierarchy(),
            events.ToImmutable()
        );

        return (
            null,
            scoped
        );
    }

    internal static string Generate(Info info, bool main, CancellationToken token)
    {
        using var writer = new IndentedTextWriter();
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable");

        using (writer.BeginHierarchy(info.Hierarchy))
        {
            if (main)
            {
                writer.Write("public sealed partial class Scoped(global::");
                writer.Write(info.Hierarchy.FullName);
                writer.WriteLine(" unscoped) : global::System.IDisposable");
            }
            else
            {
                writer.WriteLine("public partial class Scoped");
            }
            writer.WriteLine("{");
            writer.IncreaseIndent();

            if (main)
            {
                writer.Write("public global::");
                writer.Write(info.Hierarchy.FullName);
                writer.WriteLine(" Unscoped { get; } = unscoped;");
                writer.WriteLine();

                writer.Write("private record struct Sub(global::System.Action<global::");
                writer.Write(info.Hierarchy.FullName);
                writer.WriteLine(", object> Remover, object Value);");
                writer.WriteLine();

                writer.WriteLine("private readonly global::System.Collections.Generic.List<Sub> _subs = [];");
                writer.WriteLine();

                writer.WriteLine("public void Dispose()");
                writer.WriteLine("{");
                writer.IncreaseIndent();
                writer.WriteLine("foreach (var sub in _subs)");
                writer.WriteLine("{");
                writer.IncreaseIndent();
                writer.WriteLine("sub.Remover(Unscoped, sub.Value);");
                writer.DecreaseIndent();
                writer.WriteLine("}");
                writer.WriteLine("_subs.Clear();");
                writer.DecreaseIndent();
                writer.WriteLine("}");
                writer.WriteLine();
            }

            foreach (var ev in info.Events)
            {
                writer.Write("private readonly global::System.Action<global::");
                writer.Write(info.Hierarchy.FullName);
                writer.Write(", object> _Remove");
                writer.Write(ev.Name);
                writer.Write(" = static (unscoped, value) => unscoped.");
                writer.Write(ev.Name);
                writer.Write(" -= (");
                writer.Write(ev.Type);
                writer.WriteLine(") value;");

                writer.Write("public event ");
                writer.Write(ev.Type);
                writer.Write(" ");
                writer.WriteLine(ev.Name);
                writer.WriteLine("{");
                writer.IncreaseIndent();

                writer.WriteLine("add");
                writer.WriteLine("{");
                writer.IncreaseIndent();
                writer.Write("Unscoped.");
                writer.Write(ev.Name);
                writer.WriteLine(" += value;");
                writer.Write("_subs.Add(new(_Remove");
                writer.Write(ev.Name);
                writer.WriteLine(", value));");
                writer.DecreaseIndent();
                writer.WriteLine("}");

                writer.WriteLine("remove");
                writer.WriteLine("{");
                writer.IncreaseIndent();
                writer.Write("Unscoped.");
                writer.Write(ev.Name);
                writer.WriteLine(" -= value;");
                writer.Write("_subs.Remove(new(_Remove");
                writer.Write(ev.Name);
                writer.WriteLine(", value));");
                writer.DecreaseIndent();
                writer.WriteLine("}");

                writer.DecreaseIndent();
                writer.WriteLine("}");
                writer.WriteLine();
            }

            writer.DecreaseIndent();
            writer.WriteLine("}");
            writer.WriteLine();

            if (main)
            {
                writer.WriteLine("public Scoped CreateScoped() => new(this);");
                writer.WriteLine();
            }
        }

        return writer.ToString();
    }

    internal sealed record class Info(
        Hierarchy Hierarchy,
        EquatableArray<(string Type, string Name)> Events
    );
}
